from opentrons import protocol_api

requirements = {"robotType": "OT-2", "apiLevel": "2.19"}
metadata = {
    "protocolName": "VaxForge s05_expression_induction",
    "description": "Inducer addition to expression cultures",
    "author": "VaxForge S9 (generated)",
}


def run(ctx: protocol_api.ProtocolContext):
    # ---- deck -------------------------------------------------------------
    cult = ctx.load_labware("nest_96_wellplate_2ml_deep", "5")  # Expression cultures (human-inoculated)
    tubes = ctx.load_labware("opentrons_24_tuberack_nest_1.5ml_snapcap", "2")  # Inducer + vehicle
    tips_p20_1 = ctx.load_labware("opentrons_96_tiprack_20ul", "11")  # p20 tips
    tips_p300_1 = ctx.load_labware("opentrons_96_tiprack_300ul", "10")  # p300 tips
    p20 = ctx.load_instrument("p20_single_gen2", "left", tip_racks=[tips_p20_1])
    p300 = ctx.load_instrument("p300_single_gen2", "right", tip_racks=[tips_p300_1])

    # ---- initial deck contents (what the operator loads; see the setup sheet) ----
    liq_1 = ctx.define_liquid(name="expression culture (to be induced)", description="human_prepared", display_color="#33AAFF")
    liq_2 = ctx.define_liquid(name="expression culture (uninduced control)", description="human_prepared", display_color="#E8A33D")
    liq_3 = ctx.define_liquid(name="inducer stock", description="robot_loaded", display_color="#6FBF73")
    liq_4 = ctx.define_liquid(name="vehicle (same solvent, no inducer)", description="robot_loaded", display_color="#C86DD7")
    cult["A1"].load_liquid(liquid=liq_1, volume=1000)
    cult["B1"].load_liquid(liquid=liq_1, volume=1000)
    cult["C1"].load_liquid(liquid=liq_1, volume=1000)
    cult["D1"].load_liquid(liquid=liq_2, volume=1000)
    cult["E1"].load_liquid(liquid=liq_2, volume=1000)
    cult["F1"].load_liquid(liquid=liq_2, volume=1000)
    tubes["A1"].load_liquid(liquid=liq_3, volume=45)
    tubes["A2"].load_liquid(liquid=liq_4, volume=45)

    # ---- steps ------------------------------------------------------------

    # [s05] Small-scale expression and induction | ROBOT-PARTIAL | Inducer addition yes; shaking incubation no.
    ctx.comment("[s05] Small-scale expression and induction | ROBOT-PARTIAL | Inducer addition yes; shaking incubation no.")
    p20.transfer(5, tubes["A1"], [cult["A1"], cult["B1"], cult["C1"]], new_tip="always")
    p20.transfer(5, tubes["A2"], [cult["D1"], cult["E1"], cult["F1"]], new_tip="always")
    p300.pick_up_tip()
    p300.mix(5, 100, cult["A1"])
    p300.drop_tip()
    p300.pick_up_tip()
    p300.mix(5, 100, cult["B1"])
    p300.drop_tip()
    p300.pick_up_tip()
    p300.mix(5, 100, cult["C1"])
    p300.drop_tip()
    p300.pick_up_tip()
    p300.mix(5, 100, cult["D1"])
